
import { BinBuffer, Map } from '@taf/taf-stream'

/** 响应包体 */
export class BasePacket {
  iVersion: number
  cPacketType: number
  iRequestId: number
  iMessageType: number
  sServantName: string
  sFuncName: string
  iRet: number
  sBuffer: BinBuffer
  iTimeout: number
  status: Map<string, string>
  context?: Map<string, string>

  toObject(): BasePacket;

  readFromObject(json: any): void;

  toBinBuffer(): BinBuffer;
  
  static New(): BasePacket;
}

export interface client {
  compose(data: any):Buffer
}